const $=s=>document.querySelector(s), app=$('#app');
const rooms=[{id:'classic',name:'Classic Room',price:1250,size:28,cap:2,bed:'Queen bed',tag:'YOUR EVERYDAY ESCAPE',img:'https://images.unsplash.com/photo-1611892440504-42a792e24d32?auto=format&fit=crop&w=1400&q=85',desc:'Soft linen, warm oak and a quiet corner to call your own. Everything you need for an unhurried stay.'},{id:'deluxe',name:'Deluxe Room',price:1750,size:38,cap:2,bed:'King bed',tag:'A LITTLE MORE ROOM',img:'https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1400&q=85',desc:'Stretch out in a light-filled room with a king bed, a generous seating area and thoughtful details.'},{id:'suite',name:'Suite',price:2500,size:58,cap:4,bed:'King bed + sofa bed',tag:'MAKE YOURSELF AT HOME',img:'https://images.unsplash.com/photo-1566665797739-1674de7a421a?auto=format&fit=crop&w=1400&q=85',desc:'Space for slow mornings and shared moments. A separate living area makes a longer stay feel effortless.'}];
const datePlus=n=>{let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let state={checkin:datePlus(7),checkout:datePlus(9),guests:2,room:'classic',guest:{},payment:'card',confirmed:false};
try{const saved=JSON.parse(sessionStorage.getItem('stillmere')||'null');if(saved)state={...state,...saved};}catch{}
const save=()=>{try{sessionStorage.setItem('stillmere',JSON.stringify(state));}catch{}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'R'+Number(n).toLocaleString('en-ZA',{maximumFractionDigits:2});
const room=()=>rooms.find(r=>r.id===state.room)||rooms[0];
const nights=()=>Math.max(1,Math.round((new Date(state.checkout)-new Date(state.checkin))/86400000));
const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'});
const deadline=()=>{let d=new Date(state.checkin+'T12:00:00');d.setDate(d.getDate()-2);return d.toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric'})+' at 14:00 SAST'};
const toast=s=>{$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)};
const go=p=>{location.hash=p};
function search(home=false){return `<form id="search" class="search ${home?'home-search':''}"><label>CHECK-IN<input aria-label="Check-in" name="checkin" type="date" min="${datePlus(0)}" value="${state.checkin}" required></label><label>CHECK-OUT<input aria-label="Check-out" name="checkout" type="date" min="${state.checkin}" value="${state.checkout}" required></label><label>GUESTS<select name="guests">${[1,2,3,4].map(n=>`<option value="${n}" ${+state.guests===n?'selected':''}>${n} guest${n>1?'s':''}</option>`).join('')}</select></label><button>Check availability ↗</button><div class="error full" id="search-error" role="alert"></div></form>`}
const benefits=()=>`<div class="benefits"><span>Best direct rate</span><span>Breakfast included</span><span>Free cancellation within policy</span><span>VAT included · No extra fees</span></div>`;
function card(r){return `<article class="card"><a href="#room/${r.id}" aria-label="Explore ${r.name}"><img src="${r.img}" alt="${r.name} with warm neutral furnishings" loading="lazy"></a><div class="card-body"><span class="eyebrow">${r.tag}</span><h3>${r.name}</h3><div class="meta">${r.size} m² &nbsp; · &nbsp; ${r.bed} &nbsp; · &nbsp; Up to ${r.cap}</div><p>${r.desc}</p><div class="card-bottom"><div class="price">${money(r.price)}<small>per night · VAT included</small></div><a href="#room/${r.id}" class="button outline">Explore room ↗</a></div></div></article>`}
function steps(active){return `<div class="steps">${['Choose room','Guest & payment','Review','Confirmation'].map((s,i)=>`<span class="${i===active?'current':''}">${i+1}. ${s}</span>`).join('')}</div>`}
function summary(){let r=room(),total=r.price*nights();return `<aside class="panel summary"><img src="${r.img}" alt="${r.name}"><h3>${r.name}</h3><p class="meta">${fmt(state.checkin)} — ${fmt(state.checkout)}<br>${nights()} night${nights()>1?'s':''} · ${state.guests} guest${state.guests>1?'s':''}</p><a class="textbtn" href="#rooms">Change your stay</a><div class="row line"><span>${money(r.price)} × ${nights()} nights</span><strong>${money(total)}</strong></div><div class="row meta"><span>VAT included (15%)</span><span>${money(total*15/115)}</span></div><div class="row meta"><span>Additional fees</span><span>R0</span></div><div class="row line total"><span>Total</span><span>${money(total)}</span></div><div class="soft">✓ Breakfast & Wi-Fi included<br>✓ Free cancellation until ${deadline()}</div><button class="textbtn" data-policy>View booking terms</button></aside>`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">WELCOME TO STILLMERE</span><h1>A place to<br>settle in.</h1><p>Thoughtful rooms. Warm welcomes. A little space to slow down. Discover a stay that feels like it was made for you.</p><a class="button" href="#rooms">Find your room ↗</a><p class="fine">One hotel. A more personal stay.</p></div><div class="hero-photo"><img src="${rooms[0].img}" alt="Sunlit Stillmere guest room with crisp linen"><span class="photo-caption">Quiet comfort, considered in every detail.</span></div></section>${search(true)}${benefits()}<section class="wrap"><div class="section-head"><div><span class="eyebrow">REST, YOUR WAY</span><h2>Room to feel at home.</h2></div><p>From a quiet night away to a longer escape, find your own kind of comfort.</p></div><div class="cards">${rooms.map(card).join('')}</div></section><section class="strip"><span class="eyebrow">THE STILLMERE WAY</span><h2>Small details.<br>A better kind of stay.</h2><p>Good coffee. Fresh linen. A familiar welcome.<br>Simple things, thoughtfully done.</p><a class="button outline" style="color:white;border-color:#8898a8" href="#hotel">Get to know us ↗</a></section><section class="wrap"><span class="eyebrow">GUEST NOTES · ILLUSTRATIVE REVIEWS</span><h2>A few kind words.</h2><div class="reviews"><blockquote><span>★★★★★</span><p>“The kind of place that makes you wish you had booked another night.”</p><small>Alex · Weekend stay</small></blockquote><blockquote><span>★★★★★</span><p>“Quiet rooms, a lovely breakfast and the warmest welcome.”</p><small>Thandi · Couple's escape</small></blockquote><blockquote><span>★★★★★</span><p>“Everything I needed, with room to breathe.”</p><small>Sam · Business stay</small></blockquote></div></section>`}
function listing(){return `<section class="wrap"><span class="eyebrow">YOUR STAY STARTS HERE</span><h1>Find your quiet corner.</h1>${search()}<div class="filters"><span id="count"></span><label>Sort rooms<select id="sort"><option value="price">Price: low to high</option><option value="high">Price: high to low</option><option value="space">Largest first</option></select></label></div><div class="cards" id="room-list"></div><p class="fine">Demo availability: rooms are shown by guest capacity. All rates are per room, per night.</p></section>`}
function detail(id){let r=rooms.find(x=>x.id===id);if(!r)return listing();state.room=id;save();return `<section class="wrap"><a class="textbtn" href="#rooms">← All rooms</a><div class="section-head"><div><span class="eyebrow">${r.tag}</span><h1>${r.name}</h1></div><span class="pill">Breakfast included</span></div><div class="split"><div><img class="wide-photo" src="${r.img}" alt="${r.name}"><h2>Stay a little longer.</h2><p class="room-desc">${r.desc}</p><div class="amenities"><div>${r.bed}</div><div>${r.size} m² of space</div><div>Up to ${r.cap} guests</div><div>Complimentary Wi-Fi</div><div>Breakfast included</div><div>Tea & coffee station</div></div><details open><summary>Good to know</summary><p>Check-in from 14:00 · Check-out by 11:00.<br>A non-smoking room with fresh linen and daily housekeeping.</p></details><details><summary>Cancellation policy</summary><p>Free cancellation until ${deadline()}. After the deadline, the first night is charged. Illustrative terms.</p></details></div><div>${summary()}<div class="actions"><button id="book-room">Book this room ↗</button></div>${+state.guests>r.cap?'<p class="error">This room cannot accommodate your party. Choose the Suite or change your guest count.</p>':''}</div></div></section>`}
function guest(){return `<section class="wrap">${steps(1)}<span class="eyebrow">LET’S MAKE IT YOURS</span><h1>Guest & payment.</h1><div class="split"><form class="panel" id="guest-form"><h3>Your details</h3><p>Tell us who we’ll be welcoming.</p><div class="fields"><label class="full">Full name<input name="name" autocomplete="name" required minlength="2" value="${esc(state.guest.name)}" placeholder="Your full name"></label><label>Email address<input name="email" type="email" autocomplete="email" required value="${esc(state.guest.email)}" placeholder="you@example.com"></label><label>Mobile number<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{7,20}" value="${esc(state.guest.phone)}" placeholder="+27"></label><label class="full">Special requests <span class="fine">(optional)</span><textarea name="requests" rows="3" maxlength="500" placeholder="Anything we should know?">${esc(state.guest.requests)}</textarea></label></div><h3>Payment method</h3><p class="soft">Demo checkout. No payment is collected. Use the test card option below; do not enter real card details.</p><label>Choose how to pay<select name="payment"><option value="card" ${state.payment==='card'?'selected':''}>Test credit or debit card ···· 4242</option><option value="hotel" ${state.payment==='hotel'?'selected':''}>Pay at hotel (demo)</option></select></label><p class="fine">Test card: 4242 4242 4242 4242 · Expiry 12/30 · CVC 123<br>Payment is simulated automatically.</p><label class="check"><input type="checkbox" required name="terms" ${state.guest.terms?'checked':''}><span>I agree to the <button type="button" class="textbtn" data-policy>booking and cancellation terms</button>.</span></label><div class="actions"><a class="button outline" href="#room/${state.room}">← Back</a><button>Review booking ↗</button></div></form>${summary()}</div></section>`}
function review(){return `<section class="wrap">${steps(2)}<span class="eyebrow">ONE LAST LOOK</span><h1>Your stay, at a glance.</h1><div class="split"><div class="panel"><h3>Looking forward to welcoming you.</h3><p>Check the details below before confirming your demo reservation.</p><div class="row line"><strong>Guest</strong><a class="textbtn" href="#guest">Edit details</a></div><p>${esc(state.guest.name)}<br>${esc(state.guest.email)}<br>${esc(state.guest.phone)}</p><div class="row line"><strong>Payment</strong><span>${state.payment==='card'?'Test card ···· 4242':'Pay at hotel'}</span></div>${state.guest.requests?`<div class="line"><h4>Special requests</h4><p>${esc(state.guest.requests)}</p></div>`:''}<div class="soft">Free cancellation until ${deadline()}. After this deadline, the first night is charged.</div><p class="fine">This creates a demonstration booking only. No room is reserved and no email or payment is sent.</p><div class="actions"><a class="button outline" href="#guest">← Back</a><button id="confirm">Confirm demo booking ↗</button></div></div>${summary()}</div></section>`}
function confirmation(){return `<section class="wrap">${steps(3)}<div class="success"><span class="success-icon">✓</span><h1>We’ve saved you<br>a little peace of mind.</h1><p>Your demo booking is confirmed, ${esc(state.guest.name||'guest')}.<br>No real reservation or charge has been made.</p><p class="eyebrow">REFERENCE ${esc(state.reference)}</p>${summary()}<div class="actions"><button class="outline" id="download">Download confirmation</button><button id="new-stay">Plan another stay ↗</button></div></div></section>`}
function info(page){if(page==='dining')return `<section class="hero"><div class="hero-copy"><span class="eyebrow">AT OUR TABLE</span><h1>Good mornings.<br>Great company.</h1><p>Seasonal favourites, freshly brewed coffee and something worth slowing down for.</p><a class="button" href="#contact">Enquire about dining ↗</a></div><div class="hero-photo"><img src="https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1400&q=85" alt="Warm and inviting restaurant setting"></div></section><section class="wrap"><div class="cards"><div class="panel"><span class="eyebrow">07:00 — 10:00</span><h3>Breakfast, on us.</h3><p>A fresh start with seasonal fruit, warm pastries and cooked favourites. Included with every direct booking.</p></div><div class="panel"><span class="eyebrow">12:00 — 15:00</span><h3>A leisurely lunch.</h3><p>Light plates, bright flavours and a little time to reconnect. Ask our team about the seasonal menu.</p></div><div class="panel"><span class="eyebrow">18:00 — 21:00</span><h3>Evenings together.</h3><p>Thoughtfully prepared dishes in a relaxed setting. Dining arrangements are illustrative.</p></div></div></section>`;
if(page==='hotel')return `<section class="wrap"><span class="eyebrow">A WARMER WELCOME</span><h1>Considered comfort.<br>Uncomplicated hospitality.</h1><div class="split"><img class="wide-photo" src="https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1400&q=85" alt="Peaceful hotel terrace"><div><h2>A place of your own.</h2><p>Stillmere is one hotel with one simple idea: make every guest feel settled. Natural textures, gentle light and thoughtful spaces set the pace.</p><div class="amenities"><div>Daily breakfast</div><div>Complimentary Wi-Fi</div><div>Welcoming lounge</div><div>Daily housekeeping</div></div><a class="button" href="#rooms">Discover your room ↗</a></div></div><h2>A few helpful details.</h2><details><summary>When can I check in?</summary><p>Check-in begins at 14:00 and check-out is by 11:00. Ask about early arrival in your booking requests.</p></details><details><summary>Can I stay with my family?</summary><p>The Suite sleeps up to four guests. Classic and Deluxe rooms accommodate up to two.</p></details><details><summary>What is included in my rate?</summary><p>Breakfast, Wi-Fi and 15% VAT. No additional checkout fees.</p></details><details><summary>Where is the hotel?</summary><p>Stillmere is a concept property. The physical address and contact details will be added when confirmed.</p></details></section>`;
return `<section class="wrap"><span class="eyebrow">WE’RE HERE TO HELP</span><h1>Let’s talk about your stay.</h1><div class="split"><form id="contact-form" class="panel"><div class="fields"><label>Your name<input name="name" required autocomplete="name"></label><label>Email address<input name="email" type="email" required autocomplete="email"></label><label class="full">What can we help with?<select name="topic"><option>Planning a stay</option><option>Dining enquiry</option><option>Accessibility</option><option>Something else</option></select></label><label class="full">Message<textarea name="message" required rows="5" maxlength="2000"></textarea></label></div><p class="fine">Demo form: your message will not be sent.</p><button>Submit demo enquiry ↗</button><p id="contact-result" role="status"></p></form><div><h2>A personal touch.</h2><p>Whether it’s a special request, a dining question or a longer stay, we’d love to help you plan it.</p><div class="panel"><h3>Before you arrive</h3><p>Check-in · From 14:00<br>Check-out · By 11:00</p><p class="fine">Property address, email and telephone are awaiting confirmation.</p><a class="textbtn" href="#hotel">Explore common questions ↗</a></div></div></div></section>`}
function render(){let path=location.hash.slice(1)||'home';if(['guest','review'].includes(path)&&+state.guests>room().cap){go('rooms');return}if(path==='review'&&!state.guest.name){go('guest');return}if(path==='confirmation'&&!state.confirmed){go('rooms');return}app.innerHTML=path==='home'?home():path==='rooms'?listing():path.startsWith('room/')?detail(path.split('/')[1]):path==='guest'?guest():path==='review'?review():path==='confirmation'?confirmation():['hotel','dining','contact'].includes(path)?info(path):home();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+path));$('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);bind();}
function bind(){document.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>$('#policy').showModal());let sf=$('#search');if(sf){sf.elements.checkin.onchange=()=>{sf.elements.checkout.min=sf.elements.checkin.value;if(sf.elements.checkout.value<=sf.elements.checkin.value){let d=new Date(sf.elements.checkin.value+'T12:00:00');d.setDate(d.getDate()+1);sf.elements.checkout.value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}};sf.onsubmit=e=>{e.preventDefault();let f=new FormData(sf);if(f.get('checkout')<=f.get('checkin')){$('#search-error').textContent='Check-out must be after check-in.';return}let n=(new Date(f.get('checkout'))-new Date(f.get('checkin')))/86400000;if(n>30){$('#search-error').textContent='For stays longer than 30 nights, please contact us.';return}state={...state,checkin:f.get('checkin'),checkout:f.get('checkout'),guests:+f.get('guests'),confirmed:false};save();if(location.hash==='#rooms')render();else go('rooms');toast('Demo availability updated for your stay.')}}
if($('#room-list')){let update=()=>{let list=rooms.filter(r=>r.cap>=+state.guests),sort=$('#sort').value;list.sort((a,b)=>sort==='high'?b.price-a.price:sort==='space'?b.size-a.size:a.price-b.price);$('#room-list').innerHTML=list.map(card).join('');$('#count').textContent=`${list.length} rooms for ${state.guests} guest${state.guests>1?'s':''} · ${nights()} nights`};$('#sort').onchange=update;update()}
if($('#book-room'))$('#book-room').onclick=()=>{if(+state.guests>room().cap){toast('Choose the Suite for more than two guests.');return}go('guest')};
if($('#guest-form')){let f=$('#guest-form');f.oninput=()=>{let d=new FormData(f);state.guest={name:d.get('name'),email:d.get('email'),phone:d.get('phone'),requests:d.get('requests'),terms:d.get('terms')==='on'};state.payment=d.get('payment');save()};f.onsubmit=e=>{e.preventDefault();f.oninput();go('review')}}
if($('#confirm'))$('#confirm').onclick=()=>{state.confirmed=true;state.reference='SM-'+Date.now().toString(36).toUpperCase();save();go('confirmation')};
if($('#new-stay'))$('#new-stay').onclick=()=>{state.confirmed=false;save();go('rooms')};
if($('#download'))$('#download').onclick=()=>{let text=`STILLMERE HOTEL — DEMO CONFIRMATION\nReference: ${state.reference}\nGuest: ${state.guest.name}\n${room().name}\n${fmt(state.checkin)} — ${fmt(state.checkout)}\n${state.guests} guests · ${nights()} nights\nTotal: ${money(room().price*nights())}, VAT included\nFree cancellation until ${deadline()}\nThis is a prototype. No reservation, email or payment has been made.`;let u=URL.createObjectURL(new Blob([text],{type:'text/plain'}));let a=document.createElement('a');a.href=u;a.download='Stillmere-demo-confirmation.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
if($('#contact-form'))$('#contact-form').onsubmit=e=>{e.preventDefault();$('#contact-result').textContent='Thank you. Your demo enquiry is complete. No message has been sent.';e.target.reset()};}
$('.menu').onclick=()=>{let on=$('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(on))};window.addEventListener('hashchange',render);render();
